UPDATE s_group_buy_group
SET member_count = member_count + 1
WHERE id = #{id}
  AND deleted = 0
  AND status = #{status}
  AND member_count < min_people

UPDATE s_group_buy_group
SET reserved_member_count = reserved_member_count - 1
WHERE id = #{id}
  AND deleted = 0
  AND status = #{status}
  AND reserved_member_count > member_count

UPDATE s_group_buy_group
SET reserved_member_count = reserved_member_count + 1
WHERE id = #{id}
  AND deleted = 0
  AND status = #{status}
  AND reserved_member_count < min_people
